"""Ativos visuais da Plataforma Delga — logo em base64 (fundo branco removido,
recortado). Gerado a partir do arquivo oficial de logo do Grupo Delga."""

# Variante escura — texto "GRUPO" na cor original, para uso sobre fundos claros
LOGO_B64 = ""
LOGO_DATA_URI = f"data:image/png;base64,{LOGO_B64}"

# Variante clara — texto "GRUPO" recolorido para uso sobre fundos escuros/navy
LOGO_LIGHT_B64 = ""
LOGO_LIGHT_DATA_URI = f"data:image/png;base64,{LOGO_LIGHT_B64}"


# Fundo animado da tela de login — vídeo institucional comprimido (960p,
# ~24fps, sem áudio) + filtro azul diagonal por cima, os dois em base64
# pra não depender de hospedagem externa nem de arquivo estático separado.
LOGIN_VIDEO_B64 = ""
LOGIN_VIDEO_DATA_URI = f"data:video/mp4;base64,{LOGIN_VIDEO_B64}"

LOGIN_OVERLAY_B64 = ""
LOGIN_OVERLAY_DATA_URI = f"data:image/png;base64,{LOGIN_OVERLAY_B64}"
